const J = $input.first().json;
const crypto = require('crypto');
const b = J.body; const buf = Buffer.from(b.content_base64, 'base64');
const ext = (b.filename.match(/\.[A-Za-z0-9]+$/) || [''])[0].toLowerCase();
const types = {'.jpg':'image/jpeg','.jpeg':'image/jpeg','.png':'image/png','.pdf':'application/pdf','.mp3':'audio/mpeg','.mp4':'video/mp4','.txt':'text/plain'};
const magic = {'image/jpeg':['ffd8ff'],'image/png':['89504e470d0a1a0a'],'application/pdf':['255044462d'],'audio/mpeg':['494433','fffb','fff3','fff2']};
const mime = types[ext]; const errs = [];
const max = (parseInt($env.MAX_UPLOAD_MB || '5')) * 1024 * 1024;
if (!mime) errs.push('File type not allowed');
if (buf.length === 0) errs.push('Empty file');
if (buf.length > max) errs.push('File too large');
const head = buf.subarray(0, 12).toString('hex');
if (mime === 'video/mp4') { if (buf.subarray(4, 8).toString() !== 'ftyp') errs.push('Content does not match extension'); }
else if (mime === 'text/plain') { if (buf.subarray(0, 2048).includes(0)) errs.push('Binary content in .txt'); }
else if (mime && !magic[mime].some(m => head.startsWith(m))) errs.push('Content does not match extension');
const sha256 = crypto.createHash('sha256').update(buf).digest('hex');
const evidence_id = 'EV-' + crypto.randomBytes(6).toString('hex').toUpperCase();
return [{json: {valid: errs.length === 0, errors: errs, mime, size: buf.length, sha256, evidence_id, complaint_id: b.complaint_id, uploader_id: b.uploader_id, filename: b.filename, content_base64: b.content_base64}}];
